-- The ticket price of an event, in whole hryvnias. Both null: the price is unknown, as for every event stored so far,
-- so nothing is backfilled. price_min 0 without a higher price_max: free. price_max is set only together with
-- price_min and is never below it. nearby_import's table grants on events cover the columns.
ALTER TABLE "events"
    ADD COLUMN "price_min" INTEGER,
    ADD COLUMN "price_max" INTEGER,
    ADD CONSTRAINT "events_price_min_check" CHECK ("price_min" >= 0),
    ADD CONSTRAINT "events_price_max_check"
        CHECK ("price_max" IS NULL OR ("price_min" IS NOT NULL AND "price_max" >= "price_min"));
